"""Convert an arXiv (LaTeXML) HTML page to plain text. Math is replaced by its alttext."""

import re
import sys
from html.parser import HTMLParser

SKIP = {"script", "style", "nav", "header", "footer", "button", "svg"}
BLOCK = {"p", "div", "section", "h1", "h2", "h3", "h4", "h5", "h6", "li", "tr", "figcaption", "table", "br", "caption"}


class P(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.out = []
        self.skip = 0
        self.math = 0

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag in SKIP:
            self.skip += 1
            return
        if tag == "math":
            if not self.skip and not self.math:
                self.out.append(" $" + (a.get("alttext") or "") + "$ ")
            self.math += 1
            return
        if tag in BLOCK:
            self.out.append("\n")
        if tag in ("h1", "h2", "h3", "h4"):
            self.out.append("## ")
        if tag in ("td", "th"):
            self.out.append(" | ")

    def handle_endtag(self, tag):
        if tag in SKIP:
            self.skip = max(0, self.skip - 1)
            return
        if tag == "math":
            self.math = max(0, self.math - 1)
            return
        if tag in BLOCK:
            self.out.append("\n")

    def handle_data(self, data):
        if self.skip or self.math:
            return
        self.out.append(data)


def main(src, dst):
    html = open(src, encoding="utf-8", errors="replace").read()
    m = re.search(r"<article.*?</article>", html, flags=re.S)
    p = P()
    p.feed(m.group(0) if m else html)
    text = "".join(p.out)
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r"\n\s*\n+", "\n\n", text)
    open(dst, "w", encoding="utf-8").write(text.strip() + "\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])

