void psycho_1_read_freq_band (ltg, lay, freq)	/* this function reads in   */
     int lay, freq;		/* frequency bands and bark */
     g_ptr *ltg;		/* values                   */
{

#include "freqtable.h"

  int i, k;

  if ((freq < 0) || (freq > 6) || (freq == 3)) {
    printf ("Internal error (read_freq_band())\n");
    return;
  }

